import {Component, HostBinding, OnInit} from '@angular/core';
import {ActivatedRoute, NavigationExtras, Router} from '@angular/router';

import {NavController, Platform} from '@ionic/angular';
import {routeAnimation} from '../../shared';
import {Plugins, PluginListenerHandle} from '@capacitor/core';
import 'ocr';
import {isNotNullOrUndefined} from 'codelyzer/util/isNotNullOrUndefined';
import {HttpClientService} from '../../shared/http-client.service';
import {ModalService} from 'ng-zorro-antd-mobile';
import {environment} from "../../../environments/environment";
const { Ocr } = Plugins;

import 'id-card-reader';
const { IdCardReader } = Plugins;

// 扫描码
import 'scanner';
const { Scanner } = Plugins;

@Component({
    selector: 'app-person-list',
    templateUrl: 'person-list.page.html',
    styleUrls: ['person-list.page.scss'],
    animations: [    // 路由动画
        routeAnimation
    ]
})
export class PersonListPage implements OnInit{
    titleInfo = '';
    contentInfo = '';
    personList = [];
    personListLength = 0;
    model = 10;
    tubePatientId;
    right = [
        {
            text: '删除',
            onPress: () => {
                this.showDelete();
            },
            className: 'btnClass'
        }
    ];
    result: { name: string, sex: string, folk: string, birthday: string, num: string, address: string, imageData: string };
    encodeKey;
    load;
    view = '1';
    isClosedTube = '0'; // 0 开管 1 封管
    isScanModel = 'false';
    date: Date;
    SelectButtonPattern = '1'; // 1 扫描身份证 2 扫描健康码 3 读卡
    ButtonName = '扫描身份证';
    constructor(
        private router: Router,
        public navCtrl: NavController,
        private http: HttpClientService,
        private route: ActivatedRoute,
        private platform: Platform,
        private deleteModal: ModalService
    ) {
        // 控制app返回按钮
        this.platform.backButton.subscribeWithPriority(10, () => {
            this.routeBack();
        });
    }

    @HostBinding('@routeAnimation') state;   // 路由动画
    ngOnInit() {
        this.route.queryParams.subscribe(data => {
            this.load = document.getElementsByClassName('person-load-bar')[0];
            if (data['num'] !== undefined){
                // 扫试管码后，跳转界面，扫身份证
                //  this.scanIdentity();
            }
        });
    }
    ionViewWillEnter() {
        this.titleInfo = sessionStorage.getItem('tubeBarcode');
        // 模式
        if (isNotNullOrUndefined(sessionStorage.getItem('modelValue'))){
            this.model = Number(sessionStorage.getItem('modelValue'));
        } else {
            this.model = 10;
        }
        // 获取是否封管
        this.isClosedTube = sessionStorage.getItem('isClosedTube');
        // 是否直接扫描
        this.isScanModel = sessionStorage.getItem('isDirectScan');
        if (this.isScanModel === 'false'){
            // 默认选择第一个
            if (!isNotNullOrUndefined(sessionStorage.getItem('SelectButtonPattern'))){
                this.SelectButtonPattern = '1';
                sessionStorage.setItem('SelectButtonPattern', '1');
            } else {
                this.SelectButtonPattern = sessionStorage.getItem('SelectButtonPattern');
                this.changePattern( this.SelectButtonPattern);
            }
        } else {
            this.SelectButtonPattern = '1';
            sessionStorage.setItem('SelectButtonPattern', '1');
        }
        this.GetPatientTube();
    }
    // 路由返回
    routeBack() {
        this.router.navigate(['/BottleList']);
    }
    // 路由跳转
    routeFont(value) {
        if (value === 'false'){
            this.router.navigate(['/WriteIdentityFormat']);
        } else {
            sessionStorage.setItem('fullInfoStr', value['fullInfoStr']);
            value['fullInfoStr'] = '';
            value['SelectButtonPattern'] = this.SelectButtonPattern;
            const navigationExtras: NavigationExtras = {
                queryParams: value
            };
            this.router.navigate(['/WriteIdentityFormat'], navigationExtras);
        }
    }

    // 点击列表，跳转到身份证录入界面
    // 修改
    onClick(value, i){
        value.index = i;
        value.titleId = '3';
        this.routeFont(value);
    }

    // 打开删除按钮时，获取当前管子的UUID
    openDelete(uuid){
        this.tubePatientId = uuid;
    }
    notScan(value) {
        const condition = {
            name: '',
            sex: '男',
            nation: '汉',
            birthday: '',
            address: '',
            identity: '',
            phone: '',
            fullInfoStr: '',
            index: this.personListLength,
            id: '',
            memo: '本人',
            age: '',
            titleId: value
        };
        this.routeFont(condition);
    }

    // 封管操作
    confirmTubeClick() {
        this.confirmTube();
    }
    getScanCondition(phone){
        const condition = {
            name: this.result.name,
            sex: this.result.sex,
            nation: this.result.folk,
            birthday: this.result.birthday,
            address: this.result.address,
            identity: this.result.num,
            phone: phone,
            fullInfoStr: this.result.imageData,
            id: '',
            index: this.personListLength,
            barcode: sessionStorage.getItem('tubeBarcode'),
            tubeId: sessionStorage.getItem('tubeBarId'),
        };
        return condition;
    }

    changePattern(value){
        sessionStorage.setItem('SelectButtonPattern', value);
        switch (value){
            case '1':
                this.ButtonName = '扫描身份证';
                break;
            case '2':
                this.ButtonName = '扫描健康码';
                break;
            case '3':
                this.ButtonName = '证件读卡器';
                this.readIdentity();
                break;
        }
    }
    clickIdentity(){
        let bool = false;
        if (isNotNullOrUndefined(this.date)){
            if ((new Date().getTime() - this.date.getTime()) / 1000 > 1){
                bool = true;
            } else {
                bool = false;
                this.http.showToast('正在读取身份信息，请稍等');
            }
        } else {
            bool = true;
        }
        if(bool){
            this.date = new Date();
            switch (this.SelectButtonPattern){
                case '1':
                    this.scanIdentity();
                    break;
                case '2':
                    this.scanHealthCode();
                    break;
                case '3':
                    this.readIdentity();
                    break;
            }
        }
    }
    // 扫描身份证
    async scanIdentity() {
        this.result = (await Ocr.scan());
        const condition = this.getScanCondition('');
        // 未注册, 跳转填写页面
        condition['memo'] = '本人';
        condition['titleId'] = '1';
        this.routeFont(condition);
    }
    // 扫描健康码
    async scanHealthCode(){
        try {
            const result = await Scanner.openScanner();
            switch (result['operation']) {
                case 'SCAN':
                    console.log('扫描健康码结果', result['result']);
                    this.scanCode(result['result']);
                    break;
                case 'MANUAL':
                    break;
                case 'CANCEL':
                    break;
            }
        }catch (e) {
            this.http.showToast('扫描失败，请重新扫描！');
            // this.scanCode('qwe');
        }
    }
    // 读卡
    readIdentity(){
        // 判断连接成功状态
        // this.load.style.display = 'inline-block';
        if (!isNotNullOrUndefined(sessionStorage.getItem('readConnectState')) ||
            sessionStorage.getItem('readConnectState') === 'false'){
            this.connectRead();
        } else {
            this.read();
        }
    }

    async read() {
        let data;
        try {
            data = (await IdCardReader.read());
            this.load.style.display = 'none';
            if (data['code'] === 'SUCCESS'){
                this.result = {
                    address: data['address'],
                    birthday: data['birthday'],
                    folk : data['folk'],
                    name: data['name'],
                    num: data['num'],
                    sex : data['sex'],
                    imageData: ''
                };
                const condition = this.getScanCondition('');
                // 未注册, 跳转填写页面
                condition['memo'] = '本人';
                condition['titleId'] = '1';
                this.routeFont(condition);
            } else {
                this.load.style.display = 'none';
                if (data['code'] === 'FIND_CARD_FAILED'){
                    this.http.showToast('请重新放置身份证');
                }
            }
        }catch (e) {
            this.http.showToast('读卡失败，请重新放置身份证');
        }
    }
    // 连接读卡器
    connectRead(){
        // 调方法
        // 打开OPEN，关闭CLOSED
        try {
            IdCardReader.addListener('onBluetoothStateChange', (bluetoothState) => {
                console.log('onBluetoothStateChange', bluetoothState);
                if (bluetoothState === 'OPEN'){
                    // 记录连接成功状态
                    sessionStorage.setItem('readConnectState', 'true');
                    this.load.style.display = 'none';
                } else {
                    // 记录连接失败状态
                    sessionStorage.setItem('readConnectState', 'false');
                    this.load.style.display = 'none';
                }
            });
            // 连接成功CONNECTED 、 失败 NOT_CONNECTED 、 断开连接 DISCONNECT
            IdCardReader.addListener('onBluetoothConnectStateChange', (connectState) => {
                console.log('onBluetoothConnectStateChange', connectState);
                if (connectState['connectState'] === 'CONNECTED'){
                    // 记录连接成功状态
                    sessionStorage.setItem('readConnectState', 'true');
                    this.http.showToast('读卡器连接成功，请放置身份证');
                    this.load.style.display = 'none';
                } else {
                    // 记录连接失败状态
                    sessionStorage.setItem('readConnectState', 'false');
                    this.load.style.display = 'none';
                    this.http.showToast('蓝牙读卡器连接失败！');
                }
            });
            IdCardReader.connect();
        }catch(e) {
            this.http.showToast('蓝牙读卡器连接失败！');
            this.load.style.display = 'none';
        }
    }
    // 调用后台接口
    // 1. 获取当前管里的标本
    GetPatientTube(){
        const condition = {
            tubeId: sessionStorage.getItem('tubeBarId')
        };
        this.load['style']['display'] = 'inline-block';
        this.http
            .post(`rcp/api/get/tube/patient` + this.http.getParamsString(condition), {} ,
                '获取当前管里的标本', environment.FailMessage.getTubeSample)
            .subscribe( data => {
                this.load['style']['display'] = 'none';
                if (data['isSuccess']){
                    this.personList = data['data'];
                    this.personListLength =   this.personList.length;
                }
            });
    }
    // 删除采集管
    showDelete() {
        this.deleteModal.alert('', '确认删除?', [
            { text: '取消', onPress: () => {} },
            { text: '删除', onPress: () => {
                    this.deleteTube();
                }}
        ]);
    }
    deleteTube(){
        const condition = {
            tubePatientId:  this.tubePatientId,
        };
        this.http
            .post(`rcp/api/delete/tube/patient` + this.http.getParamsString(condition) , {},
                '删除采集患者', environment.FailMessage.deleteSample)
            .subscribe( data => {
                // 删除成功后，重新获取当前管子里的标本列表
                if (data['isSuccess']){
                    this.GetPatientTube();
                }
            });
    }
    // 封管操作
    confirmTube(){
        const condition = {
            boxBarId:  sessionStorage.getItem('boxBarId'),
            tubeBarId: sessionStorage.getItem('tubeBarId'),
            tubeBarcode: sessionStorage.getItem('tubeBarcode'),
            tubeState: 'CloseBar'
        };
        this.http
            .get(`rcp/api/tube/operate/confirmTube`, condition , '确认采集管', 'false')
            .subscribe( data => {
                if (data['code'] === '0'){
                    if (isNotNullOrUndefined(data['message'])) {
                        this.http.showToast(data['message']);
                    } else {
                        this.router.navigate(['/BottleBarcode']);
                    }
                    // if (isNotNullOrUndefined(data['message'])) {
                    //     // 封管时已封箱-扫码新箱
                    //     const navigationExtras: NavigationExtras = {
                    //         queryParams: { boxBarcode: sessionStorage.getItem('boxBarcode')}
                    //     };
                    //     this.router.navigate(['/tabs/tab1'], navigationExtras);
                    // } else {
                    //     // 封管后跳转到扫采集管界面
                    //     this.router.navigate(['/BottleBarcode']);
                    // }
                }
            });
    }
    assignmentValue(condition, item){
        // 身份信息
        condition.nation = item.nation;
        condition.birthday = item.birthday;
        condition.sex = item.sex;
        condition.identity = item.idenno;
        condition.name = item.patientName;
        condition.phone = item.mobile;
        condition.address = item.address;
        condition.memo = item.relationship;
        condition.id = item.id;
        return condition;
    }
    // 扫描身份证
    scanCode(value){
        const condition = {
            ehealthCode:  value,
        };
        this.http
            .post(`lstrcp/api/scan` + this.http.getParamsString(condition), {} , '扫描健康码', 'false')
            .subscribe( data => {
              if (data['code'] === '0'){
                    if (data['data']['ret_code'] === '0000'){
                        const cond = data['data']['biz_content'];
                        const condJson = JSON.parse(cond);
                        let birthdayStr = '';
                        if (isNotNullOrUndefined(condJson['birthday']) && condJson['birthday'] !== ''){
                            birthdayStr =  condJson['birthday'].substr(0, 4) + '年' + condJson['birthday'].substr(4, 2)
                                + '月' + condJson['birthday'].substr(6, 2) + '日';
                        }
                        const conditionJson = {
                            name: condJson['user_name'],
                            sex: condJson['user_sex'] === '1' ? '男' : '女',
                            nation: condJson['nation'],
                            birthday: birthdayStr,
                            address: condJson['address'] + condJson['detail_address'],
                            identity: condJson['id_no'],
                            phone: condJson['mobile_phone'],
                            fullInfoStr: '',
                            id: '',
                            index: this.personListLength,
                            barcode: sessionStorage.getItem('tubeBarcode'),
                            tubeId: sessionStorage.getItem('tubeBarId'),
                        };
                        // 未注册, 跳转填写页面
                        conditionJson['memo'] = '本人';
                        conditionJson['titleId'] = '1';
                        this.routeFont(conditionJson);
                    } else {
                        this.http.showToast(data['data']['ret_msg']);
                    }
                } else {
                    this.http.showToast('扫描失败，请重新扫描！');
                }
            });
    }
}
